import {createFlight,step,guidance,clamp} from './physics.js';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d');
let flight=createFlight(),auto=false,paused=false,keys=new Set(),last=0,accumulator=0,w=800,h=710,particles=[],touch={left:false,right:false,burn:false};
const stars=Array.from({length:95},(_,i)=>({x:((i*7919)%997)/997,y:((i*2377)%991)/991,r:i%5===0?1.4:.65}));
function reset(){flight=createFlight($('weather').value);paused=false;particles=[];keys.clear();touch={left:false,right:false,burn:false};$('throttle').value=0;$('pause').textContent='Pause';$('overlay').classList.remove('hidden');$('overline').textContent='700 METERS. ONE LANDING.';$('message').textContent='Your window is open.';$('detail').textContent='Brake your descent. Keep the ship upright. Touch down inside the illuminated pad.';$('launch').innerHTML='Release Starship <span>↗</span>';}
function launch(){if(flight.status!=='ready')reset();flight.status='flying';canvas.tabIndex=0;canvas.focus();$('overlay').classList.add('hidden');}
function setMode(value){auto=value;$('manual').classList.toggle('selected',!auto);$('assist').classList.toggle('selected',auto);$('manual').setAttribute('aria-pressed',!auto);$('assist').setAttribute('aria-pressed',auto);$('modehint').textContent=auto?'Guidance has control. Watch the ship correct its approach.':'You have control. Small corrections go a long way.';$('throttle').disabled=auto;}
function pause(){if(flight.status!=='flying')return;paused=!paused;$('pause').textContent=paused?'Resume':'Pause';}
$('launch').onclick=launch;$('reset').onclick=reset;$('pause').onclick=pause;$('manual').onclick=()=>setMode(false);$('assist').onclick=()=>setMode(true);$('weather').onchange=reset;
for(const id of ['left','right','burn']){$(id).onpointerdown=e=>{e.preventDefault();$(id).setPointerCapture(e.pointerId);touch[id]=true};$(id).onpointerup=$(id).onpointercancel=()=>touch[id]=false;}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='KeyP')pause();if(!e.repeat&&e.code==='KeyR')reset();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();touch={left:false,right:false,burn:false};if(flight.status==='flying'&&!paused)pause();});
function finish(){const landed=flight.status==='landed';$('overlay').classList.remove('hidden');$('overline').textContent=landed?'CONTACT CONFIRMED':flight.status==='lost'?'OUT OF RANGE':'FLIGHT ENDED';$('message').textContent=landed?'Welcome back, Starship.':flight.status==='lost'?'Beyond the range.':'A little too ambitious.';$('detail').textContent=landed?`Touchdown at ${Math.abs(flight.vy).toFixed(1)} m/s. ${Math.round(flight.fuel)}% fuel remaining. ${auto?'Guidance brought you home.':'That landing was all you.'}`:`${Math.abs(flight.vy).toFixed(1)} m/s vertical · ${Math.abs(flight.vx).toFixed(1)} m/s lateral · ${Math.abs(flight.x).toFixed(0)} m from pad. ${auto?'Try another approach.':'Try Autoland to see a controlled approach.'}`;$('launch').innerHTML='Fly again <span>↗</span>';}
function tick(dt){if(paused||flight.status!=='flying')return;let power=Number($('throttle').value)/100;if(keys.has('ArrowUp'))power=clamp(power+dt*.5,0,1);if(keys.has('ArrowDown'))power=clamp(power-dt*.5,0,1);$('throttle').value=power*100;const input=auto?guidance(flight):{turn:(keys.has('KeyD')||keys.has('ArrowRight')||touch.right?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')||touch.left?1:0),throttle:keys.has('Space')||touch.burn?1:power};step(flight,input,dt);if(flight.status!=='flying')finish();}
function draw(){const dpr=Math.min(devicePixelRatio||1,2);const box=canvas.getBoundingClientRect();if(w!==box.width||h!==box.height||canvas.width!==Math.round(box.width*dpr)){w=box.width;h=box.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#080f1b');sky.addColorStop(.65,'#142b3b');sky.addColorStop(1,'#30444a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);for(const s of stars){ctx.globalAlpha=.3+s.r*.25;ctx.fillStyle='#d5e4f1';ctx.beginPath();ctx.arc(s.x*w,s.y*h*.72,s.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
const ground=h-120,scale=Math.min((h-240)/800,w/850),cx=w*.55;const px=cx+flight.x*scale,py=ground-flight.y*scale-18;
ctx.strokeStyle='#abcde012';ctx.lineWidth=1;ctx.font='11px monospace';ctx.fillStyle='#8ea7b570';for(let a=100;a<=1000;a+=100){const y=ground-a*scale;if(y<150)continue;ctx.beginPath();ctx.moveTo(25,y);ctx.lineTo(w-25,y);ctx.stroke();ctx.fillText(a+' m',w-65,y-6)}
ctx.fillStyle='#091319';ctx.fillRect(0,ground+12,w,h-ground);ctx.strokeStyle='#40565e';ctx.beginPath();ctx.moveTo(0,ground+12);ctx.lineTo(w,ground+12);ctx.stroke();
// Landing footprint and approach corridor are functional flight guides.
ctx.setLineDash([4,8]);ctx.strokeStyle='#caff8025';ctx.beginPath();ctx.moveTo(cx,150);ctx.lineTo(cx,ground);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#caff80';ctx.shadowColor='#caff80';ctx.shadowBlur=15;ctx.fillRect(cx-26*scale,ground+5,52*scale,3);ctx.shadowBlur=0;for(const sign of [-1,1]){ctx.fillStyle='#caff80';ctx.fillRect(cx+sign*32*scale-2,ground,4,8)}ctx.font='12px monospace';ctx.fillStyle='#b7c6ce';ctx.fillText('PAD A',cx-18,ground+35);
if(flight.status==='flying'&&flight.throttle>0&&!paused){for(let i=0;i<2;i++)particles.push({x:px-Math.sin(flight.angle)*23,y:py+Math.cos(flight.angle)*23,vx:-Math.sin(flight.angle)*2+(Math.random()-.5),vy:Math.cos(flight.angle)*2,life:1});}particles=particles.filter(p=>p.life>0);for(const p of particles){if(!paused){p.x+=p.vx;p.y+=p.vy;p.life-=.025}ctx.globalAlpha=p.life*.35;ctx.fillStyle='#95c4d7';ctx.beginPath();ctx.arc(p.x,p.y,3+(1-p.life)*8,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
if(flight.status==='crashed'){ctx.strokeStyle='#e3a374';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px,ground,28,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(px-10,ground-10);ctx.lineTo(px+10,ground+10);ctx.moveTo(px+10,ground-10);ctx.lineTo(px-10,ground+10);ctx.stroke();}else{ctx.save();ctx.translate(px,py);ctx.rotate(flight.angle);if(flight.throttle>0){ctx.fillStyle='#caff80';ctx.shadowColor='#caff80';ctx.shadowBlur=18;ctx.beginPath();ctx.moveTo(-5,19);ctx.lineTo(0,20+flight.throttle*(20+Math.random()*16));ctx.lineTo(5,19);ctx.fill();ctx.shadowBlur=0;}const metal=ctx.createLinearGradient(-8,0,8,0);metal.addColorStop(0,'#526777');metal.addColorStop(.45,'#e5eef2');metal.addColorStop(1,'#8296a4');ctx.fillStyle=metal;ctx.beginPath();ctx.moveTo(-7,18);ctx.lineTo(-7,-14);ctx.quadraticCurveTo(-6,-24,0,-30);ctx.quadraticCurveTo(6,-24,7,-14);ctx.lineTo(7,18);ctx.closePath();ctx.fill();ctx.fillStyle='#607b8c';for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(side*6,3);ctx.lineTo(side*14,19);ctx.lineTo(side*6,16);ctx.fill();ctx.beginPath();ctx.moveTo(side*6,-16);ctx.lineTo(side*10,-8);ctx.lineTo(side*6,-9);ctx.fill()}ctx.fillStyle='#263a48';ctx.fillRect(-3,-13,6,3);ctx.restore();}
if(flight.status==='flying'){ctx.strokeStyle='#caff80';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(px+22,py);ctx.lineTo(px+40,py);ctx.stroke();ctx.fillStyle='#d3e6ef';ctx.font='11px monospace';ctx.fillText(auto?'GUIDANCE':'STARSHIP',px+45,py+4)}
$('alt').textContent=Math.round(flight.y);$('speed').innerHTML=`${flight.vy.toFixed(1)} <small>m/s</small>`;$('offset').innerHTML=`${Math.round(flight.x)} <small>m</small>`;$('tilt').innerHTML=`${Math.round(flight.angle*180/Math.PI)} <small>°</small>`;$('fuel').innerHTML=`${Math.round(flight.fuel)} <small>%</small>`;$('fuelbar').style.width=flight.fuel+'%';$('power').textContent=Math.round(flight.throttle*100)+'%';$('phase').textContent=paused?'FLIGHT PAUSED':({ready:'AWAITING RELEASE',flying:auto?'GUIDANCE ACTIVE':'MANUAL FLIGHT',landed:'TOUCHDOWN',crashed:'SIGNAL LOST',lost:'OUT OF RANGE'})[flight.status];$('clock').textContent=`T+ ${String(Math.floor(flight.time/60)).padStart(2,'0')}:${String(Math.floor(flight.time%60)).padStart(2,'0')}`;
}
function frame(now){accumulator+=Math.min((now-last)/1000,.1);last=now;while(accumulator>=1/120){tick(1/120);accumulator-=1/120}draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
window.starfall={getState:()=>({...flight,mode:auto?'autoland':'manual',paused}),restart:reset,launch,setMode,pause};
if(document.modelContext?.registerTool){
 const lifetime=new AbortController();
 const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}};
 register({name:'read_flight',description:'Read the current Starfall flight and control mode.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.starfall.getState()});
 register({name:'start_flight',description:'Reset and release a new Starfall flight with manual or autoland control.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['manual','autoland']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['manual','autoland'].includes(input.mode)||Object.keys(input).some(k=>k!=='mode'))throw new Error('Choose manual or autoland.');reset();setMode(input.mode==='autoland');launch();return window.starfall.getState();}});
 window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
}
